arguments.old:
difference() {
    union() {
        gear_solid(z1);
        // detent flange, a ring on edge radius 12 with four deep V
        // notches: the base bump clicks in every quarter turn
        rotate_extrude($fn = 96)
            polygon(points = [[9, 5], [12, 5], [12, 7.5], [9, 7.5]]);
        // crank peg, standing up at radius 7.5 (clear of the notches)
        translate([0, 7.5, gear_h]) cylinder(r = 2.6, h = 11.5, $fn = 36);
    }
    translate([0, 0, -1]) cylinder(r = bore_r, h = 20, $fn = 48);
    for (a = [0, 90, 180, 270])
        rotate([0, 0, a]) translate([0, -10.6, gear_h - 0.2])
            cylinder(r1 = 1.2, r2 = 2.6, h = 2.9, $fn = 32);
}

arguments.new:
difference() {
    union() {
        gear_solid(z1);
        // detent plate on the gear, dipping 0.7 below the gear top so
        // its underside bridges only 0.6 above the gear top face
        translate([0, 0, gear_h - 0.7]) cylinder(r = 12, h = 3.2, $fn = 72);
        // crank peg, standing up at radius 7.5 (clear of the notches)
        translate([0, 7.5, gear_h]) cylinder(r = 2.6, h = 11.5, $fn = 36);
    }
    translate([0, 0, -1]) cylinder(r = bore_r, h = 20, $fn = 48);
    // four deep V notches: the base bump clicks in every quarter turn
    for (a = [0, 90, 180, 270])
        rotate([0, 0, a]) translate([0, -10.6, gear_h - 1.5])
            cylinder(r1 = 2.6, r2 = 1.2, h = 4.2, $fn = 32);
}
